# AI: below section was generated by an AI
"""
Edge color extraction ("取四周的颜色").

Splits an image/video-frame into four border bands (top / right / bottom / left)
and returns the dominant color of each band. Used to map a video frame's
surrounding colors onto the four LED segments of a TV-backlight style layout.

Usage:
    python3 scripts/color_edges.py <image_url_or_path> [--band 0.12] [--stops 3]

Output: JSON with {success, edges:{top,right,bottom,left}, order:[...]}
"""
import json
import os
import sys

SCRIPT_DIR = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, SCRIPT_DIR)

from analyze_image import load_image, rgb_to_hsv

# Canonical edge order for a clockwise TV-backlight layout.
EDGE_ORDER = ["top", "right", "bottom", "left"]


def split_edge_bands(img, band_ratio=0.12, min_px=8):
    """Crop the four border bands of an image. Returns {edge_name: PIL.Image}."""
    w, h = img.size
    bw = max(min_px, int(w * band_ratio))
    bh = max(min_px, int(h * band_ratio))
    bw = min(bw, max(1, w // 2))
    bh = min(bh, max(1, h // 2))
    return {
        "top": img.crop((0, 0, w, bh)),
        "right": img.crop((w - bw, 0, w, h)),
        "bottom": img.crop((0, h - bh, w, h)),
        "left": img.crop((0, 0, bw, h)),
    }


def _band_colors(band, stops=3):
    """Dominant colors of a band, dark pixels filtered, sorted by ratio.

    Uses quantize + getcolors() (no deprecated Image.getdata()).
    """
    rgb_band = band.convert("RGB")
    raw = []
    try:
        quant = rgb_band.quantize(colors=max(8, stops * 4), method=2)  # 2 = MEDIANCUT
        palette = quant.getpalette()
        for cnt, idx in (quant.getcolors(maxcolors=rgb_band.width * rgb_band.height) or []):
            raw.append(((palette[idx * 3], palette[idx * 3 + 1], palette[idx * 3 + 2]), cnt))
    except Exception:
        raw = []

    if not raw:
        avg = rgb_band.resize((1, 1)).getpixel((0, 0))
        raw = [(avg, 1)]

    total = sum(c for _, c in raw) or 1
    entries = []
    for rgb, cnt in raw:
        r, g, b = rgb
        _, _, v = rgb_to_hsv(r, g, b)
        if v < 15:          # near-black band -> ignore, fall back later
            continue
        entries.append({
            "rgb": [r, g, b],
            "hex": "#{:02X}{:02X}{:02X}".format(r, g, b),
            "ratio": round(cnt / total, 4),
        })

    if not entries:
        avg = rgb_band.resize((1, 1)).getpixel((0, 0))
        r, g, b = avg
        entries = [{
            "rgb": [r, g, b],
            "hex": "#{:02X}{:02X}{:02X}".format(r, g, b),
            "ratio": 1.0,
        }]

    total = sum(e["ratio"] for e in entries) or 1.0
    for e in entries:
        e["ratio"] = round(e["ratio"] / total, 4)
    entries.sort(key=lambda x: x["ratio"], reverse=True)
    return entries[:stops]


def extract_edge_colors(img, band_ratio=0.12, stops=3):
    """Return {edges:{top,right,bottom,left}, order:[...]} for one frame."""
    bands = split_edge_bands(img, band_ratio=band_ratio)
    edges = {}
    for name, band in bands.items():
        colors = _band_colors(band, stops=stops)
        edges[name] = {
            "rgb": colors[0]["rgb"],
            "hex": colors[0]["hex"],
            "ratio": colors[0]["ratio"],
            "colors": colors,
        }
    return {"edges": edges, "order": EDGE_ORDER}


def edge_colors_for_source(source, band_ratio=0.12, stops=3):
    """Convenience wrapper: load image (no quality gate) then extract edges."""
    img = load_image(source, validate_quality=False)
    return extract_edge_colors(img, band_ratio=band_ratio, stops=stops)


def main():
    if "--help" in sys.argv or "-h" in sys.argv or len(sys.argv) < 2:
        print(__doc__)
        sys.exit(0)

    source = sys.argv[1]
    band_ratio = 0.12
    stops = 3
    i = 2
    while i < len(sys.argv):
        if sys.argv[i] == "--band" and i + 1 < len(sys.argv):
            band_ratio = float(sys.argv[i + 1]); i += 2
        elif sys.argv[i] == "--stops" and i + 1 < len(sys.argv):
            stops = int(sys.argv[i + 1]); i += 2
        else:
            i += 1

    try:
        result = edge_colors_for_source(source, band_ratio=band_ratio, stops=stops)
        result["success"] = True
        result["image_source"] = source
        print(json.dumps(result, indent=2, ensure_ascii=False))
    except Exception as e:
        print(json.dumps({"success": False, "error": str(e), "image_source": source},
                         indent=2, ensure_ascii=False))
        sys.exit(1)


if __name__ == "__main__":
    main()
# AI: end
